CREATE TABLE `ws_sale_order`
(
    `sale_order_id`         BIGINT(20) NOT NULL AUTO_INCREMENT COMMENT 'order id',
    `sale_order_code`       VARCHAR(100)        DEFAULT NULL COMMENT 'order code',
    `customer_id`           BIGINT(20)          DEFAULT NULL COMMENT 'customer id',
    `invoice_customer_id`   BIGINT(20)          DEFAULT NULL COMMENT 'invoice customer id',
    `channel_id`            BIGINT(20)          DEFAULT NULL COMMENT 'channel id',
    `goods_id`              BIGINT(20)          DEFAULT NULL COMMENT 'goods id',
    `bid_price`             DECIMAL(10, 2)      DEFAULT '0.00' COMMENT 'list price',
    `sell_price`            DECIMAL(14, 6)      DEFAULT '0.000000' COMMENT 'sale price',
    `sale_num`              DECIMAL(10, 3)      DEFAULT '0.000' COMMENT 'sale quantity',
    `sale_order_price`      DECIMAL(20, 6)      DEFAULT '0.000000' COMMENT 'order amount',
    `payment_type`          INT(5)              DEFAULT NULL COMMENT 'payment type',
    `reimbursement_date`    DATE                DEFAULT NULL COMMENT 'report date',
    `residue_credit_amount` DECIMAL(20, 6)      DEFAULT NULL COMMENT 'remaining credit',
    `order_state`           INT(5)              DEFAULT NULL COMMENT 'order state',
    `invoice_state`         INT(5)              DEFAULT '0' COMMENT 'invoice state',
    `is_split`              INT(5)              DEFAULT '0' COMMENT 'split state',
    `income_state`          INT(5)              DEFAULT '0' COMMENT 'income state',
    `sale_day_review_id`    BIGINT(20)          DEFAULT NULL COMMENT 'day review id',
    `create_user_id`        BIGINT(20)          DEFAULT NULL COMMENT 'create user id',
    `create_time`           DATETIME            DEFAULT CURRENT_TIMESTAMP COMMENT 'create time',
    `update_user_id`        BIGINT(20)          DEFAULT NULL COMMENT 'update user id',
    `update_time`           DATETIME            DEFAULT CURRENT_TIMESTAMP COMMENT 'update time',
    `plan_code`             VARCHAR(50)         DEFAULT NULL COMMENT 'plan code',
    `red_rush_order_code`   VARCHAR(50)         DEFAULT NULL COMMENT 'reversal code',
    `sale_type`             INT(5)              DEFAULT NULL COMMENT '0-wholesale, 1-retail',
    `submit_time`           DATETIME            DEFAULT CURRENT_TIMESTAMP COMMENT 'submit time',
    `bind_state`            INT(11)             DEFAULT '150' COMMENT 'bind state',
    `income_amount`         DECIMAL(20, 2)      DEFAULT '0.00' COMMENT 'related income amount',
    `lock_price`            INT(2)     NOT NULL DEFAULT '0' COMMENT 'lock price flag',
    `lock_price_order_code` VARCHAR(20)         DEFAULT NULL COMMENT 'related lock price order code',
    PRIMARY KEY (`sale_order_id`),
    UNIQUE KEY `unique_salecode` (`sale_order_code`),
    KEY `idx_cid` (`customer_id`) USING BTREE,
    KEY `idx_icid` (`invoice_customer_id`) USING BTREE,
    KEY `idx_gid` (`goods_id`) USING BTREE,
    KEY `idx_sdrid` (`sale_day_review_id`) USING BTREE,
    KEY `idx_rd` (`reimbursement_date`) USING BTREE,
    KEY `idx_lpdc` (`lock_price_order_code`) USING BTREE
) ENGINE = InnoDB
  AUTO_INCREMENT = 25414
  DEFAULT CHARSET = utf8mb4 COMMENT = 'sales order table';
